def select_explanation_examples(object_name: str, count: int = 3) -> str:
    """Return stable, rotating examples so prompts stay small and reproducible."""
    if not EXPLANATION_STYLE_EXAMPLES or count <= 0:
        return ""
    start = sum(ord(character) for character in object_name.lower()) % len(EXPLANATION_STYLE_EXAMPLES)
    examples = [EXPLANATION_STYLE_EXAMPLES[(start + offset) % len(EXPLANATION_STYLE_EXAMPLES)] for offset in range(min(count, len(EXPLANATION_STYLE_EXAMPLES)))]
    return "\n\n".join(
        f"VERIFIED FACTS: {facts}\nCHILD-FRIENDLY EXPLANATION: {explanation}"
        for facts, explanation in examples
    )
